-- =====================================================================
--  03_DCL_SALES_KEYS_AFTER_LOAD.sql  -  business keys and foreign keys
--
--  All constraints here are ENABLE NOVALIDATE:
--  * existing (legacy) rows are NOT checked, so nothing is rejected or lost;
--  * every NEW insert/update from the new application IS checked.
--  Part A = business unique keys, Part B = foreign keys,
--  Part C = check queries that list legacy duplicates / orphans.
--  When Part C shows 0 for a constraint, you can make it fully trusted:
--    ALTER TABLE <t> ENABLE VALIDATE CONSTRAINT <name>;
-- =====================================================================
SET DEFINE OFF
WHENEVER SQLERROR CONTINUE

-- ---------------------------------------------------------------- A. business unique keys

